1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	const CURSE_SURCHARGE_RATE = 0.5;
58	const HIGH_ENCHANTMENT_THRESHOLD = 5;
59	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
60	const LOYALTY_THRESHOLD_YEARS = 2;
61	const LOYALTY_DISCOUNT_RATE = 0.2;
62	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
63	const DEDUCTIBLE_PER_DAMAGE = 100;
64	const CAP_MULTIPLIER = 2;
65	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
66	const HALF_REIMBURSEMENT_RATE = 0.5;
67	
68	// The price list: one row per insurable item type. The two numbers are
69	// independent columns — the premium is what the customer pays to insure the
70	// item, the insured value is what the MHPCO would owe for it.
71	interface ItemSpec {
72	  basePremium: number;
73	  insuredValue: number;
74	}
75	
76	const ITEM_SPECS: Record<string, ItemSpec> = {
77	  sword: { basePremium: 100, insuredValue: 1000 },
78	  amulet: { basePremium: 60, insuredValue: 600 },
79	  staff: { basePremium: 80, insuredValue: 800 },
80	  potion: { basePremium: 40, insuredValue: 400 },
81	  rune: { basePremium: 25, insuredValue: 250 },
82	  moonstone: { basePremium: 25, insuredValue: 250 },
83	};
84	
85	const BLOCK_SIZE = 3;
86	const BLOCK_BASE_PREMIUM = 60;
87	
88	const countByType = (items: Item[]): Map<string, number> => {
89	  const counts = new Map<string, number>();
90	  for (const item of items) {
91	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
92	  }
93	  return counts;
94	};
95	
96	// The single point where an item type is resolved. Every price lookup goes
97	// through here, so an unknown type cannot slip into any calculation.
98	const specOfType = (type: string): ItemSpec => {
99	  const spec = ITEM_SPECS[type];
100	  if (spec === undefined) {
101	    throw new Error(`unknown item type: ${type}`);
102	  }
103	  return spec;
104	};
105	
106	const basePremiumOfType = (type: string): number => specOfType(type).basePremium;
107	
108	const insuredValueOfType = (type: string): number => specOfType(type).insuredValue;
109	
110	const basePremiumOfAlikeItems = (type: string, count: number): number =>
111	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumOfType(type);
112	
113	const policyBasePremium = (items: Item[]): number =>
114	  [...countByType(items)].reduce(
115	    (total, [type, count]) => total + basePremiumOfAlikeItems(type, count),
116	    0,
117	  );
118	
119	const firstInsuranceSurcharge = (policyBase: number): number =>
120	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE;
121	
122	const itemBasePremium = (item: Item): number => basePremiumOfType(item.type);
123	
124	const isCursed = (item: Item): boolean => item.cursed === true;
125	
126	const isHighlyEnchanted = (item: Item): boolean =>
127	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
128	
129	const curseSurcharge = (item: Item): number =>
130	  isCursed(item) ? itemBasePremium(item) * CURSE_SURCHARGE_RATE : 0;
131	
132	const highEnchantmentSurcharge = (item: Item): number =>
133	  isHighlyEnchanted(item)
134	    ? itemBasePremium(item) * HIGH_ENCHANTMENT_SURCHARGE_RATE
135	    : 0;
136	
137	const itemSurchargeTotal = (items: Item[]): number =>
138	  items.reduce(
139	    (total, item) => total + curseSurcharge(item) + highEnchantmentSurcharge(item),
140	    0,
141	  );
142	
143	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
144	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS
145	    ? policyBase * LOYALTY_DISCOUNT_RATE
146	    : 0;
147	
148	const followUpContractDiscount = (policyBase: number, previousQuotes: number): number =>
149	  previousQuotes > 0 ? policyBase * FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
150	
151	const policyWideAdjustments = (
152	  policyBase: number,
153	  customer: Customer,
154	  previousQuotes: number,
155	): number =>
156	  firstInsuranceSurcharge(policyBase) -
157	  loyaltyDiscount(policyBase, customer) -
158	  followUpContractDiscount(policyBase, previousQuotes);
159	
160	const quote = (
161	  step: QuoteStep,
162	  customer: Customer,
163	  previousQuotes: number,
164	): QuoteResult => {
165	  const policyBase = policyBasePremium(step.items);
166	  const premiumBeforeRounding =
167	    policyBase +
168	    itemSurchargeTotal(step.items) +
169	    policyWideAdjustments(policyBase, customer, previousQuotes) +
170	    PROCESSING_FEE;
171	  return { premium: Math.ceil(premiumBeforeRounding) };
172	};
173	
174	interface Policy {
175	  items: Item[];
176	  remainingCap: number;
177	}
178	
179	const insuranceSum = (items: Item[]): number =>
180	  items.reduce((total, item) => total + insuredValueOfType(item.type), 0);
181	
182	const isHalfCovered = (item: Item): boolean =>
183	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
184	
185	// How much of the damage the policy covers, before the deductible is taken off.
186	const coveredAmount = (damage: Damage, item: Item): number =>
187	  isHalfCovered(item) ? damage.amount * HALF_REIMBURSEMENT_RATE : damage.amount;
188	
189	const payoutForDamage = (damage: Damage, item: Item): number =>
190	  Math.max(0, coveredAmount(damage, item) - DEDUCTIBLE_PER_DAMAGE);
191	
192	const damagedItem = (policy: Policy, damage: Damage): Item => {
193	  const item = policy.items.find((insured) => insured.type === damage.itemType);
194	  if (item === undefined) {
195	    throw new Error(`damaged item is not covered by the policy: ${damage.itemType}`);
196	  }
197	  return item;
198	};
199	
200	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
201	  const desiredPayout = step.incident.damages.reduce(
202	    (total, damage) => total + payoutForDamage(damage, damagedItem(policy, damage)),
203	    0,
204	  );
205	  const payout = Math.min(desiredPayout, policy.remainingCap);
206	  policy.remainingCap -= payout;
207	  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
208	};
209	
210	const policyFor = (items: Item[]): Policy => ({
211	  items,
212	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
213	});
214	
215	const countQuotesBefore = (steps: Step[], stepIndex: number): number =>
216	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
217	
218	export const runScenario = (scenario: Scenario): ScenarioOutput => {
219	  // A policy is registered under the index of the step that quoted it; that
220	  // step index is the id later claim steps refer to. Claims mutate their
221	  // policy's remainingCap, so the register carries state across steps.
222	  const policies = new Map<number, Policy>();
223	
224	  const results = scenario.steps.map((step, stepIndex): StepResult => {
225	    if (step.op === "claim") {
226	      return claim(step, policies.get(step.policy)!);
227	    }
228	    policies.set(stepIndex, policyFor(step.items));
229	    return quote(
230	      step,
231	      scenario.customer,
232	      countQuotesBefore(scenario.steps, stepIndex),
233	    );
234	  });
235	
236	  return { results };
237	};
