// A claim is all-or-nothing: every damage entry is validated and priced before
// the cap is touched, so a claim that turns out to be invalid cannot leave a
// partial decrement behind for later steps to inherit.
const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
  const desiredPayout = step.incident.damages
    .map((damage) => payoutForDamage(damage, damagedItem(policy, damage)))
    .reduce((total, amount) => total + amount, 0);

  const payout = Math.min(desiredPayout, policy.remainingCap);
  policy.remainingCap -= payout;
  return { payout: Math.floor(payout), remainingCap: policy.remainingCap };
};

